<?php

declare(strict_types=1);

use Sigilbase\Dto\Checkpoint;
use Sigilbase\Dto\Event;
use Sigilbase\Dto\InclusionProof;
use Sigilbase\Dto\PublicKey;
use Sigilbase\Dto\PublicKeySet;
use Sigilbase\Tests\Support\FixtureProofs;
use Sigilbase\Tests\Support\VendoredVerifier;
use Sigilbase\Verify\ProofVerifier;

/**
 * Real crypto, no mocks: bundles are generated by the vendored verifier
 * FixtureGenerator (fresh Ed25519 keypair, real chain, real trees) and the
 * SDK's verifier must agree with the published implementation on all of it.
 */
beforeEach(function () {
    $this->dir = sys_get_temp_dir().'/sigilbase-php-fixtures-'.bin2hex(random_bytes(6));
    // Five events in checkpoints of two: exercises multi-leaf paths and the
    // single-leaf checkpoint (5..5) whose audit path is empty.
    VendoredVerifier::writeBundle($this->dir, eventCount: 5, perCheckpoint: 2);
    $this->keys = FixtureProofs::keySet($this->dir);
});

afterEach(function () {
    foreach (glob($this->dir.'/*') ?: [] as $file) {
        @unlink($file);
    }

    @rmdir($this->dir);
});

function eventWith(Event $event, array $overrides): Event
{
    return new Event(
        id: $overrides['id'] ?? $event->id,
        sequence: $overrides['sequence'] ?? $event->sequence,
        occurredAt: $overrides['occurredAt'] ?? $event->occurredAt,
        receivedAt: $overrides['receivedAt'] ?? $event->receivedAt,
        actor: $overrides['actor'] ?? $event->actor,
        action: $overrides['action'] ?? $event->action,
        resource: array_key_exists('resource', $overrides) ? $overrides['resource'] : $event->resource,
        payload: $overrides['payload'] ?? $event->payload,
        payloadHash: $overrides['payloadHash'] ?? $event->payloadHash,
        prevHash: $overrides['prevHash'] ?? $event->prevHash,
        entryHash: $overrides['entryHash'] ?? $event->entryHash,
        checkpointId: $event->checkpointId,
    );
}

function checkpointWith(Checkpoint $checkpoint, array $overrides): Checkpoint
{
    return new Checkpoint(
        id: $checkpoint->id,
        sequenceFrom: $overrides['sequenceFrom'] ?? $checkpoint->sequenceFrom,
        sequenceTo: $overrides['sequenceTo'] ?? $checkpoint->sequenceTo,
        merkleRoot: $overrides['merkleRoot'] ?? $checkpoint->merkleRoot,
        prevCheckpointHash: $overrides['prevCheckpointHash'] ?? $checkpoint->prevCheckpointHash,
        checkpointHash: $overrides['checkpointHash'] ?? $checkpoint->checkpointHash,
        signature: $overrides['signature'] ?? $checkpoint->signature,
        publicKey: $overrides['publicKey'] ?? $checkpoint->publicKey,
        createdAt: $overrides['createdAt'] ?? $checkpoint->createdAt,
    );
}

function proofWith(InclusionProof $proof, array $overrides): InclusionProof
{
    return new InclusionProof(
        streamId: $overrides['streamId'] ?? $proof->streamId,
        streamSlug: $proof->streamSlug,
        event: $overrides['event'] ?? $proof->event,
        leafIndex: $overrides['leafIndex'] ?? $proof->leafIndex,
        auditPath: $overrides['auditPath'] ?? $proof->auditPath,
        merkleRoot: $overrides['merkleRoot'] ?? $proof->merkleRoot,
        checkpoint: $overrides['checkpoint'] ?? $proof->checkpoint,
    );
}

it('verifies every event of a real bundle, including the single-leaf checkpoint', function () {
    foreach (range(1, 5) as $sequence) {
        $proof = FixtureProofs::proof($this->dir, $sequence);
        $result = ProofVerifier::verify($proof, $this->keys);

        expect($result->verified)->toBeTrue(
            "sequence {$sequence}: ".implode('; ', $result->failures),
        );
    }
});

it('fails when the payload content was modified', function () {
    $proof = FixtureProofs::proof($this->dir, 2);
    $payload = clone $proof->event->payload;
    $payload->note = 'rewritten history';

    $result = ProofVerifier::verify(
        proofWith($proof, ['event' => eventWith($proof->event, ['payload' => $payload])]),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('payload_hash does not match');
});

it('fails when an event field was modified', function () {
    $proof = FixtureProofs::proof($this->dir, 2);

    $result = ProofVerifier::verify(
        proofWith($proof, ['event' => eventWith($proof->event, ['actor' => 'user:evil'])]),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('entry_hash does not recompute');
});

it('fails when the proof claims a different stream', function () {
    $proof = FixtureProofs::proof($this->dir, 2);

    $result = ProofVerifier::verify(
        proofWith($proof, ['streamId' => '11111111-2222-3333-4444-555555555555']),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('entry_hash does not recompute')
        ->and(implode(' ', $result->failures))->toContain('checkpoint_hash does not recompute');
});

it('fails when an audit path hash was tampered', function () {
    $proof = FixtureProofs::proof($this->dir, 1);
    $path = $proof->auditPath;
    $path[0] = new Sigilbase\Dto\AuditPathStep(strrev($path[0]->hash), $path[0]->side);

    $result = ProofVerifier::verify(proofWith($proof, ['auditPath' => $path]), $this->keys);

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('audit path does not lead');
});

it('fails when the leaf index lies about the event position', function () {
    $proof = FixtureProofs::proof($this->dir, 1);

    $result = ProofVerifier::verify(proofWith($proof, ['leafIndex' => 1]), $this->keys);

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('leaf_index does not match');
});

it('fails when the checkpoint was re-dated', function () {
    $proof = FixtureProofs::proof($this->dir, 2);

    $result = ProofVerifier::verify(
        proofWith($proof, ['checkpoint' => checkpointWith($proof->checkpoint, [
            'createdAt' => '2026-07-01T23:59:59.000000Z',
        ])]),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('checkpoint_hash does not recompute');
});

it('fails when the signature is forged', function () {
    $proof = FixtureProofs::proof($this->dir, 2);
    $signature = $proof->checkpoint->signature;
    $flipped = (dechex(hexdec($signature[0]) ^ 0x1)).substr($signature, 1);

    $result = ProofVerifier::verify(
        proofWith($proof, ['checkpoint' => checkpointWith($proof->checkpoint, ['signature' => $flipped])]),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('signature does not verify');
});

it('fails when the signing key is not in the published set', function () {
    $proof = FixtureProofs::proof($this->dir, 2);

    $otherKeys = new PublicKeySet([new PublicKey(
        publicKey: bin2hex(sodium_crypto_sign_publickey(sodium_crypto_sign_keypair())),
        algorithm: 'ed25519',
        createdAt: '2026-01-01T00:00:00.000000Z',
        retiredAt: null,
    )]);

    $result = ProofVerifier::verify($proof, $otherKeys);

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('not in the published signing keys');
});

it('still trusts retired keys for checkpoints signed while active', function () {
    $proof = FixtureProofs::proof($this->dir, 2);

    $retired = new PublicKeySet([new PublicKey(
        publicKey: $this->keys->keys[0]->publicKey,
        algorithm: 'ed25519',
        createdAt: '2026-01-01T00:00:00.000000Z',
        retiredAt: '2026-06-01T00:00:00.000000Z',
    )]);

    expect(ProofVerifier::verify($proof, $retired)->verified)->toBeTrue();
});

it('rejects malformed hex before touching any crypto', function () {
    $proof = FixtureProofs::proof($this->dir, 2);

    $result = ProofVerifier::verify(
        proofWith($proof, ['event' => eventWith($proof->event, ['entryHash' => 'zz'.substr($proof->event->entryHash, 2)])]),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(implode(' ', $result->failures))->toContain('not a 64-character hex hash');
});

it('reports every failed check, not just the first', function () {
    $proof = FixtureProofs::proof($this->dir, 2);
    $payload = clone $proof->event->payload;
    $payload->note = 'rewritten';

    $result = ProofVerifier::verify(
        proofWith($proof, [
            'event' => eventWith($proof->event, ['payload' => $payload, 'actor' => 'user:evil']),
            'leafIndex' => 99,
        ]),
        $this->keys,
    );

    expect($result->verified)->toBeFalse()
        ->and(count($result->failures))->toBeGreaterThanOrEqual(3);
});
